{
  "_task": {
    "id": "7e43e38f24f9524e6be7b6c6",
    "type": "fact_extraction",
    "entity_id": "9c1854d0142a88dcd1ea427b",
    "input_digest": "fe25b477ec86b367f77559c2dd930fb9"
  },
  "title": "An Internet for the KV Cache: Rethinking Classical Infrastructure Boundaries in the LLM Inference Age",
  "event_hint": "Vision paper proposing global-scale KV Cache content distribution system",
  "problem": "Model-side KV Cache optimizations and system-side transfer/storage optimizations evolve independently within legacy cloud boundaries, preventing optimal placement of compute and KV Cache storage across clouds and datacenters",
  "mechanism": "Proposes 'Internet for the KV Cache' vision where KV Cache management works as content-distribution system with global control plane (directory service, placement planner, prefetch scheduler) enabling store-anywhere-use-everything with bandwidth-aware movement and reuse-horizon-based tiering (hot/warm/cold)",
  "evidence": [
    {
      "claim": "Transferring 1 GB KV Cache over fully utilized 10-Gbps link is ~19x faster and ~5.2x cheaper than AWS 8xB200 GPU cluster compute",
      "value": "~5.2x cheaper, ~19x faster",
      "baseline": "AWS 8xB200 GPU cluster (~15s, $0.47)",
      "condition": "1 GB KV Cache transfer over fully utilized 10-Gbps link",
      "source_locator": "PDF Page 2, Introduction section"
    },
    {
      "claim": "Storage-compute locality is core restriction in cloud pricing due to egress costs dominating bulk data movement",
      "value": null,
      "baseline": null,
      "condition": "Wide-area cloud movement is slow and egress prices dominate cost",
      "source_locator": "PDF Page 5, Section 4.1 discussion"
    },
    {
      "claim": "KV Cache reuse horizons span seconds to hours in agentic workflows, enabling temporal slack for storage-compute tradeoffs",
      "value": null,
      "baseline": null,
      "condition": "Agentic workflows with multi-step reasoning, tool calls, code execution",
      "source_locator": "PDF Page 5, Section 4.2 discussion"
    },
    {
      "claim": "Placement governed by jointly considering reuse rates, deadlines, bandwidth, transfer and recomputation costs",
      "value": null,
      "baseline": null,
      "condition": "Model metrics (prefill FLOPs, KV size), infrastructure metrics (GPU/storage cost, bandwidth), application metrics (reuse frequency, turns)",
      "source_locator": "PDF Page 1, Abstract and PDF Page 2, Introduction section"
    },
    {
      "claim": "Paper positions as 'call for arms' rather than implemented system",
      "value": null,
      "baseline": null,
      "condition": "Vision paper without concrete implementation or evaluation",
      "source_locator": "PDF Page 7, Final section"
    }
  ],
  "evaluation_context": "Vision paper without empirical evaluation. Quantitative examples drawn from public cloud pricing documents and prior work. Proposes three-tier storage model (hot near GPU, warm intermediate, cold distant) driven by reuse horizons. References existing systems: SkyPilot, SkyServe for inter-cloud compute; Mooncake for disaggregated KV Cache; various cache compression/eviction techniques.",
  "limitations": "Vision paper without implemented system or end-to-end evaluation. Transfer cost comparison assumes fully utilized 10-Gbps link; real-world WAN conditions with congestion, variable latency not modeled. No quantitative assessment of control plane overhead, consistency mechanisms, or failure handling. Does not address multi-tenant security or cache poisoning risks.",
  "project_relevance": "Directly addresses TPN project questions on whether network can感知 KV Cache placement and whether network-side optimization adds value beyond GPU memory scheduling. Vision proposes network as active distribution channel where bandwidth/latency/pricing directly determine KV Cache management. However, lacks concrete TTFT/TPOT measurements or comparison to state-aware network scheduling. No implementation to validate whether proposed global control plane actually improves token throughput or P95 latency versus current cloud-local approaches.",
  "primary_source_resolved": true,
  "quality_score": 60,
  "evidence_gaps": [
    {
      "question": "What are the quantitative TTFT, TPOT, or P95 latency improvements from implementing the proposed Internet for KV Cache versus current cloud-local approaches?",
      "terms": ["TTFT", "TPOT", "P95", "latency", "evaluation", "end-to-end", "throughput", "performance"]
    },
    {
      "question": "What are the control plane overheads for KV Cache directory lookup, placement planning, and prefetch scheduling in real-time inference workloads?",
      "terms": ["control plane", "overhead", "directory", "placement", "prefetch", "latency", "scheduling"]
    },
    {
      "question": "How does the proposed system handle consistency, eviction, and multi-tenant isolation across regions and clouds?",
      "terms": ["consistency", "isolation", "multi-tenant", "eviction", "cross-region", "security"]
    }
  ]
}

